shop-card-media.css:
& > [data-card-alt] {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.4s ease;
}
a:hover > & > [data-card-alt],
a:focus-visible > & > [data-card-alt] {
  opacity: 1;
}
& > [data-card-alt] > * {
  height: 100%;
}
@media (prefers-reduced-motion: reduce) {
  & > [data-card-alt] {
    transition: none;
  }
}

shop-quick-buy.css:
& select {
  width: 100%;
}
& > button {
  justify-content: center;
}
& > button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

shop-tile.css:
& img {
  transition: transform 0.6s ease;
}
&:hover img {
  transform: scale(1.04);
}
@media (prefers-reduced-motion: reduce) {
  & img {
    transition: none;
  }
}

shop-banner.css:
& > [data-banner-image] {
  position: absolute;
  inset: 0;
}
& > [data-banner-image] > * {
  height: 100%;
}
& > [data-banner-image]::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgb(0 0 0 / 0.6), rgb(0 0 0 / 0.1));
}
& h1, & p, & a {
  color: inherit;
}
